INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES (1, 0, 0, 7, 129811, "エリコ班の急成長は\n騎士団の中でも話題に\nなってたからな\nホントすげえ奴等だよ", 7011, 0, 0, 11, 6);
INSERT INTO `v1_b5dac760a46ea19534c7fcb6627f6b13cb3eb7d8345325bfd253bf4c370158e2` VALUES ("", "", "", 7, 0, "", 7012, "", "", 91, "");
